import requests

def fetch_text(u,timeout=60):
    r=requests.get(u,timeout=timeout)
    r.raise_for_status()
    b=r.content
    try:
        return b.decode('utf-8',errors='replace').lstrip('\ufeff')
    except Exception:
        return b
