import io,requests
from docx import Document

def extract_docx_text(u,timeout=60):
    r=requests.get(u,timeout=timeout)
    r.raise_for_status()
    doc=Document(io.BytesIO(r.content))
    out=[(p.text or '').strip() for p in doc.paragraphs if (p.text or '').strip()]
    for t in doc.tables:
        for row in t.rows:
            out.append(' | '.join((c.text or '').strip() for c in row.cells))
    return '\n'.join(out)
